    AutocompleteMatch match;
    match.url = history_match->url;
    match.description = history_match->title;
    match.score = score;

    // Format term matches for URL and title
    FormatTermMatches(match.url, history_match->url_match_positions, &match.url_highlight_start, &match.url_highlight_end);
    FormatTermMatches(match.description, history_match->title_match_positions, &match.description_highlight_start, &match.description_highlight_end);

    // Set inline autocomplete offsets if applicable
    if (history_match->inline_autocomplete_offset > 0) {
        match.inline_autocomplete_offset = history_match->inline_autocomplete_offset;
    }

    return match;
}

