AutocompleteMatch ConvertHistoryMatchToAutocompleteMatch(const ScoredHistoryMatch* history_match, int score) {
    AutocompleteMatch match;
    memset(&match, 0, sizeof(match));

    match.url = history_match->url;
    match.title = history_match->title;
    match.description = history_match->description;
    match.score = score;

    // Format the URL and description for display
    FormatForDisplay(match.url, match.formatted_url, sizeof(match.formatted_url));
    FormatForDisplay(match.description, match.formatted_description, sizeof(match.formatted_description));

    // Set inline autocomplete offsets if applicable
    if (history_match->has_inline_match) {
        match.inline_offset = history_match->inline_offset;
    }

    // Format term matches for both URL and title
    FormatTermMatches(match.url, match.title, match.formatted_term_matches,
                      sizeof(match.formatted_term_matches));

    return match;
}

AutocompleteMatch ConvertScoredHistoryMatchToAutocompleteMatch(
    const ScoredHistoryMatch& history_match, int score) {
  AutocompleteMatch match;
  match.type = AutocompleteMatchType::HISTORY_URL;
  match.url = history_match.url;
  match.title = history_match.title;
  match.description = history_match.description;
  match.relevance = score;

  // Format the URL for display.
  match.fill_into = history_match.url.spec();

  // Format the title with inline matches.
  match.contents = history_match.title;
  match.contents_class.clear();
  for (const auto& match_info : history_match.match) {
    if (!match_info.is_url_match)
      continue;
    match.contents_class.push_back({match_info.offset, match_info.length,
                                    ACMatchClass::URL});
  }

  // Set the destination URL.
  match.destination_url = history_match.url;

  // Set the inline autocomplete offset if applicable.
  if (history_match.has_inline_autocomplete) {
    const size_t inline_offset =
        history_match.inline_autocomplete_offset;
    match.contents.insert(inline_offset, kInlineAutocompleteString);
    match.fill_into.insert(inline_offset, kInlineAutocompleteString);
    match.contents_class.insert(
        match.contents_class.begin(),
        ACMatchClass(inline_offset, strlen(kInlineAutocompleteString),
                     ACMatchClass::INLINE_AUTOCOMPLETE));
  }

  return match;
}
